    "solution": "#include <assert.h>\n#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\n#include <stdlib.h>\n#include <string.h>\n#include <math.h>\n#include <limits.h>\ntypedef struct{uint32_t coins;uint16_t level;}Save;uint8_t checksum(const uint8_t*p,size_t n){uint8_t sum=0;for(size_t i=0;i<n;i++)sum=(uint8_t)(sum+p[i]);return sum;}void encode(Save s,uint8_t*out){out[0]='S';out[1]=2;for(int i=0;i<4;i++)out[2+i]=(uint8_t)(s.coins>>(8*i));out[6]=(uint8_t)s.level;out[7]=(uint8_t)(s.level>>8);out[8]=checksum(out,8);}bool decode(const uint8_t*b,size_t n,Save*out){if(n<2||b[0]!='S')return false;if(b[1]==2){if(n!=9||b[8]!=checksum(b,8))return false;out->coins=(uint32_t)b[2]|((uint32_t)b[3]<<8)|((uint32_t)b[4]<<16)|((uint32_t)b[5]<<24);out->level=(uint16_t)(b[6]|(b[7]<<8));return true;}if(b[1]==1){if(n!=6||b[5]!=checksum(b,5))return false;out->coins=b[2]|(b[3]<<8);out->level=b[4];return true;}return false;}",
    "tests": "int main(void) { uint8_t b[9];encode((Save){0x01020304,0x0506},b);uint8_t expected[]={0x53,2,4,3,2,1,6,5,0x6A};assert(memcmp(b,expected,9)==0);Save out;assert(decode(b,9,&out)&&out.coins==0x01020304&&out.level==0x0506);b[8]^=1;assert(!decode(b,9,&out));uint8_t v1[]={0x53,1,0x2C,1,7,0x88};assert(decode(v1,6,&out)&&out.coins==300&&out.level==7);assert(!decode(NULL,0,&out)); return 0; }\n"
