    "solution": "#include <assert.h>\n#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\n#include <stdlib.h>\n#include <string.h>\n#include <math.h>\n#include <limits.h>\ndouble score(const double*c,size_t n){double s=1;for(size_t i=0;i<n;i++)s*=fmax(0,fmin(1,c[i]));return s;}bool pick(const double*s,size_t n,int current,double inertia,size_t*out){if(!n)return false;size_t best=0;double v=s[0]+(current==0?inertia:0);for(size_t i=1;i<n;i++){double x=s[i]+(current==(int)i?inertia:0);if(x>v){best=i;v=x;}}*out=best;return true;}",
