    "solution": "#include <assert.h>\n#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\n#include <stdlib.h>\n#include <string.h>\n#include <math.h>\n#include <limits.h>\ntypedef enum{SUCCESS,FAILURE,RUNNING}Status;typedef enum{LEAF,SEQUENCE,SELECTOR,INVERTER}Kind;typedef struct{Kind kind;size_t a,b;}Node;Status tick(const Node*nodes,const size_t*kids,const Status*results,size_t root){Node n=nodes[root];switch(n.kind){case LEAF:return results[n.a];case INVERTER:{Status s=tick(nodes,kids,results,n.a);return s==SUCCESS?FAILURE:s==FAILURE?SUCCESS:RUNNING;}case SEQUENCE:for(size_t i=n.a;i<n.a+n.b;i++){Status s=tick(nodes,kids,results,kids[i]);if(s!=SUCCESS)return s;}return SUCCESS;case SELECTOR:for(size_t i=n.a;i<n.a+n.b;i++){Status s=tick(nodes,kids,results,kids[i]);if(s!=FAILURE)return s;}return FAILURE;}return FAILURE;}",
