    "solution": "#include <assert.h>\n#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\n#include <stdlib.h>\n#include <string.h>\n#include <math.h>\n#include <limits.h>\ntypedef struct{double a,b,c,d,tx,ty;}Mat;typedef struct{double x,y;}Point;Mat translate(double x,double y){return (Mat){1,0,0,1,x,y};}Mat rotate(double rad){double co=cos(rad),si=sin(rad);return (Mat){co,si,-si,co,0,0};}Mat scale(double x,double y){return (Mat){x,0,0,y,0,0};}Mat mul(Mat p,Mat c){return (Mat){p.a*c.a+p.c*c.b,p.b*c.a+p.d*c.b,p.a*c.c+p.c*c.d,p.b*c.c+p.d*c.d,p.a*c.tx+p.c*c.ty+p.tx,p.b*c.tx+p.d*c.ty+p.ty};}Point apply(Mat m,Point p){return (Point){m.a*p.x+m.c*p.y+m.tx,m.b*p.x+m.d*p.y+m.ty};}bool inverse(Mat m,Mat*out){double det=m.a*m.d-m.b*m.c;if(fabs(det)<1e-12)return false;double a=m.d/det,b=-m.b/det,c=-m.c/det,d=m.a/det;*out=(Mat){a,b,c,d,-(a*m.tx+c*m.ty),-(b*m.tx+d*m.ty)};return true;}",
